CREATE TABLE IF NOT EXISTS studio_daily_usage (
	day VARCHAR(10) NOT NULL, 
	images INTEGER NOT NULL, 
	videos INTEGER NOT NULL, 
	PRIMARY KEY (day)
);

alter table studio_daily_usage enable row level security;
revoke all on table studio_daily_usage from anon, authenticated;

CREATE TABLE IF NOT EXISTS studio_generations (
	id VARCHAR(32) NOT NULL, 
	user_id VARCHAR(64) NOT NULL, 
	kind VARCHAR(8) NOT NULL, 
	source VARCHAR(12) NOT NULL, 
	template_id VARCHAR(64), 
	parent_id VARCHAR(32), 
	model VARCHAR(40) NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	params JSON NOT NULL, 
	input_keys JSON NOT NULL, 
	output_key VARCHAR(255), 
	output_mime VARCHAR(40), 
	error_public TEXT, 
	refunded BOOLEAN NOT NULL, 
	deleted BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	lease_until TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_gen_status_created ON studio_generations (status, created_at);

CREATE INDEX IF NOT EXISTS ix_gen_user_created ON studio_generations (user_id, created_at);

alter table studio_generations enable row level security;
revoke all on table studio_generations from anon, authenticated;

CREATE TABLE IF NOT EXISTS studio_rate_events (
	id SERIAL NOT NULL, 
	bucket VARCHAR(120) NOT NULL, 
	at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_rate_bucket_at ON studio_rate_events (bucket, at);

alter table studio_rate_events enable row level security;
revoke all on table studio_rate_events from anon, authenticated;

CREATE TABLE IF NOT EXISTS studio_users (
	id VARCHAR(64) NOT NULL, 
	email VARCHAR(320) NOT NULL, 
	images_used INTEGER NOT NULL, 
	videos_used INTEGER NOT NULL, 
	image_allowance INTEGER NOT NULL, 
	video_allowance INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

alter table studio_users enable row level security;
revoke all on table studio_users from anon, authenticated;

-- Private file storage. Files only leave through short-lived links the server signs after checking ownership.
